/**
 * Which source modules a page's scripts hold, and which of them ran — read
 * from each script's source map and V8 precise coverage.
 *
 * - `readScriptMaps(page, hrefs)`: fetch each script and its `<href>.map`
 *   (from the page, so its caches and origin apply) and index the mappings.
 * - `modulesOf(maps)`: every source module those scripts hold, with the
 *   generated bytes each one occupies (characters of the script mapped to
 *   it — an attribution, so a script's unmapped glue counts for no module).
 * - `startCoverage(cdp)` / `takeCoverage(cdp)`: V8 precise coverage (call
 *   counts) between the two calls; `ranModules(coverage, maps)` maps it onto
 *   the source modules (the maps may be read after the coverage was taken). A route chunk wraps each source
 *   module in its own `__esmMin` init function, so a module whose init ran
 *   was INITIALISED; a module with any other function run was CALLED (the
 *   2026-11-13 meaning of "ran"). A module whose only code is top-level
 *   statements never counts as called — the method's known blind spot.
 *
 * Used by the cold-start warm-load benchmark and the website's home-load.
 */
import type { CDPSession, Page } from "playwright";

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/** Per generated line, the [column, source index] segments in column order. */
function decodeMappings(mappings: string): [number, number][][] {
  const lines: [number, number][][] = [];
  let source = 0;
  for (const line of mappings.split(";")) {
    const segs: [number, number][] = [];
    let col = 0;
    for (const seg of line.split(",")) {
      if (seg === "") continue;
      const fields: number[] = [];
      let value = 0;
      let shift = 0;
      for (const ch of seg) {
        const digit = B64.indexOf(ch);
        value += (digit & 31) << shift;
        if (digit & 32) shift += 5;
        else {
          fields.push(value & 1 ? -(value >>> 1) : value >>> 1);
          value = 0;
          shift = 0;
        }
      }
      col += fields[0] ?? 0;
      if (fields.length >= 4) {
        source += fields[1] ?? 0;
        segs.push([col, source]);
      }
    }
    lines.push(segs);
  }
  return lines;
}

/** One script with its source map, indexed. */
export interface ScriptMap {
  href: string;
  text: string;
  sources: string[];
  lineStarts: number[];
  lines: [number, number][][];
}

/** The source module a generated offset of the script belongs to. */
export function sourceAt(map: ScriptMap, offset: number): string | null {
  let lo = 0;
  let hi = map.lineStarts.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if ((map.lineStarts[mid] ?? 0) <= offset) lo = mid;
    else hi = mid - 1;
  }
  const col = offset - (map.lineStarts[lo] ?? 0);
  const segs = map.lines[lo] ?? [];
  let best: number | null = null;
  for (const [c, s] of segs) {
    if (c > col) break;
    best = s;
  }
  return best === null ? null : (map.sources[best] ?? null);
}

/** A source module from an npm package (not our code). */
export const isNpmSource = (source: string): boolean =>
  source.includes("node_modules/");

/** Fetch each script and its `.map` from the page; scripts without a map are left out. */
export async function readScriptMaps(
  page: Page,
  hrefs: readonly string[],
): Promise<Map<string, ScriptMap>> {
  const raw = await page.evaluate(async (hs) => {
    const got: {
      href: string;
      text: string;
      map: { sources: string[]; mappings: string } | null;
    }[] = [];
    for (const href of hs) {
      const text = await (await fetch(href)).text();
      const res = await fetch(`${href}.map`);
      got.push({
        href,
        text,
        map: res.ok
          ? ((await res.json()) as { sources: string[]; mappings: string })
          : null,
      });
    }
    return got;
  }, hrefs);
  const maps = new Map<string, ScriptMap>();
  for (const { href, text, map } of raw) {
    if (map === null) continue;
    const lineStarts = [0];
    for (let i = 0; i < text.length; i++)
      if (text[i] === "\n") lineStarts.push(i + 1);
    maps.set(href, {
      href,
      text,
      sources: map.sources,
      lineStarts,
      lines: decodeMappings(map.mappings),
    });
  }
  return maps;
}

/**
 * Every source module the scripts hold → the generated characters mapped to
 * it, summed over the scripts (a segment runs to the next segment on its line,
 * or the line's end).
 */
export function modulesOf(
  maps: Iterable<ScriptMap>,
): Map<string, { chars: number }> {
  const out = new Map<string, { chars: number }>();
  for (const map of maps) {
    for (const s of map.sources) if (!out.has(s)) out.set(s, { chars: 0 });
    for (let l = 0; l < map.lines.length; l++) {
      const segs = map.lines[l] ?? [];
      const lineStart = map.lineStarts[l] ?? 0;
      const lineEnd =
        (map.lineStarts[l + 1] ?? map.text.length + 1) - 1 - lineStart;
      for (let i = 0; i < segs.length; i++) {
        const [col, src] = segs[i]!;
        const end = segs[i + 1]?.[0] ?? lineEnd;
        const name = map.sources[src];
        if (name === undefined) continue;
        const e = out.get(name)!;
        e.chars += Math.max(0, end - col);
      }
    }
  }
  return out;
}

/** Start V8 precise coverage (call counts) on a page's session — before the navigation. */
export async function startCoverage(cdp: CDPSession): Promise<void> {
  await cdp.send("Profiler.enable");
  await cdp.send("Profiler.startPreciseCoverage", {
    callCount: true,
    detailed: false,
  });
}

/** One script's coverage: its functions' first range (count, offset). */
export interface ScriptCoverage {
  url: string;
  functions: {
    functionName: string;
    ranges: { startOffset: number; count: number }[];
  }[];
}

/** The coverage since `startCoverage`, per script. */
export async function takeCoverage(cdp: CDPSession): Promise<ScriptCoverage[]> {
  const { result } = (await cdp.send("Profiler.takePreciseCoverage")) as {
    result: ScriptCoverage[];
  };
  return result;
}

/** The source modules of the mapped scripts that ran in `scripts`. */
export function ranModules(
  scripts: readonly ScriptCoverage[],
  maps: ReadonlyMap<string, ScriptMap>,
): { initialised: Set<string>; called: Set<string> } {
  const initialised = new Set<string>();
  const called = new Set<string>();
  for (const s of scripts) {
    const map = maps.get(s.url);
    if (map === undefined) continue;
    for (const f of s.functions) {
      const r = f.ranges[0];
      if (r === undefined || r.count === 0 || r.startOffset === 0) continue;
      const src = sourceAt(map, r.startOffset);
      if (src === null) continue;
      initialised.add(src);
      const before = map.text.slice(
        Math.max(0, r.startOffset - 12),
        r.startOffset,
      );
      const isInit =
        f.functionName.startsWith("init_") || /__esmMin\(\(?$/.test(before);
      if (!isInit) called.add(src);
    }
  }
  return { initialised, called };
}
